  const alert = document.createElement('div');
  alert.className = 'alert';
  alert.setAttribute('role', 'alert');
  alert.hidden = true;
  const filterLabel = document.createElement('label');
  filterLabel.textContent = 'Task filter';
  const filter = document.createElement('select');
  filter.setAttribute('aria-label', 'Task filter');
  for (const value of ['All', 'Open', 'Completed']) {
    const option = document.createElement('option');
    option.textContent = value;
    option.value = value;
    filter.append(option);
  }
  filterLabel.append(filter);
  app.append(form, alert, filterLabel);
  async function renderTasks() {
    app.querySelectorAll('[data-testid="task-row"]').forEach(row => row.remove());
    const response = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`);
    const tasks = await response.json();
    for (const task of tasks) {
      if (filter.value === 'Open' && task.completed || filter.value === 'Completed' && !task.completed) continue;
      const row = document.createElement('div');
      row.className = 'task-row';
      row.dataset.testid = 'task-row';
      const taskLabel = document.createElement('label');
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = task.completed;
      checkbox.setAttribute('aria-label', `Complete ${task.title}`);
      checkbox.addEventListener('change', async () => {
        await fetch(`/api/tasks/${task.id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
        renderTasks();
      });
      const title = document.createElement('span');
      title.textContent = task.title;
      taskLabel.append(checkbox, title);
      row.append(taskLabel);
      app.append(row);
    }
  }
  filter.addEventListener('change', renderTasks);
  form.addEventListener('submit', async event => {
    event.preventDefault();
    const title = input.value.trim();
    if (!title) { alert.textContent = 'Task title is required'; alert.hidden = false; return; }
    const response = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title }) });
    if (response.ok) { input.value = ''; alert.hidden = true; await renderTasks(); }
  });
  await renderTasks();
}

